int Mark(int value) { Print("mark " + value); return value; }
long Join(long first, int second, long third = 30) => first * 100 + second * 10 + third;
void Show(int first, int second) { Print(first * 10 + second); }
void Main() {
    Print(Join(second: Mark(2), first: Mark(1)));
    Show(second: Mark(4), first: Mark(3));
    Print(Join(first: Mark(5), Mark(6), third: Mark(7)));
    var value = 0;
    Print(Join(second: value = 1, first: value = value + 1));
    Print(value);
}
